/**
 * Sanitises a base name for the given Azure resource type.
 *
 * Steps:
 * 1. Strip characters not allowed by the type's pattern.
 * 2. For lowercase-only types (`st`, `psql`, `sql`), force lower-case.
 * 3. Truncate to `maxLen`.
 * 4. Ensure the name is not empty (falls back to the abbreviation).
 *
 * @param resourceType - The short Azure resource type key (e.g. `'vm'`).
 * @param baseName     - The raw name to sanitise.
 * @returns A name that satisfies the type's constraints.
 */
export function sanitizeAzureName(
  resourceType: string,
  baseName: string,
): string {
  const constraint = AZURE_NAME_LIMITS.get(resourceType);

  if (!constraint) {
    // Unknown type — basic sanitisation: alphanumeric + dash, max 80
    const cleaned = baseName.replace(/[^a-zA-Z0-9_-]/g, '-').slice(0, 80);
    return cleaned || 'resource';
  }

  let name = baseName;

  // Force lowercase for types that require it
  if (constraint.lowercaseOnly) {
    name = name.toLowerCase();
  }

  // Strip disallowed characters by testing each char against the pattern
  // We build a character-class regex from the constraint pattern.
  name = stripDisallowed(name, constraint.pattern);

  // Truncate
  if (name.length > constraint.maxLen) {
    name = name.slice(0, constraint.maxLen);
  }

  // Ensure non-empty
  if (name.length === 0) {
    name = constraint.abbrev;
  }

  return name;
}

/**
 * Removes characters from `input` that do not match the given full-string
 * pattern. We test character-by-character; multi-char constraints (like
 * "starts with letter") are handled as a post-step.
 */
function stripDisallowed(input: string, pattern: RegExp): string {
  // Extract the character class from patterns like /^[a-zA-Z0-9._-]+$/
  const classMatch = /^\^\[([^\]]+)\]\+\$$/.exec(pattern.source);
  if (!classMatch) {
    // For patterns like /^[a-z][a-zA-Z0-9-]*$/, do a simpler approach:
    // keep only alphanumeric + dash + underscore + dot, then test the result
    const cleaned = input.replace(/[^a-zA-Z0-9._-]/g, '');
    return cleaned;
  }

  const charClassContent = classMatch[1]!;
  const charRegex = new RegExp(`[${charClassContent}]`);
  return [...input].filter((ch) => charRegex.test(ch)).join('');
}
